Sure! Here’s the C++ equivalent of the provided Python code. Note that I'll make some adjustments due to differences in how lists, dictionaries, and random number generation are handled in C++ compared to Python.

### Converted Code:
```cpp
#include <iostream>
#include <vector>
#include <cstdlib> // For rand and srand
#include <ctime>   // For time
#include <map>     // For using dictionaries (key-value pairs)

int main() {
    // Initialize the list
    std::vector<int> list = {0, 10, 20, 30, 40, 50, 60, 70};

    // Printing list[1:6:2] equivalent (Python slicing)
    std::cout << "Sliced list: ";
    for (int i = 1; i < 6; i += 2) {
        std::cout << list[i] << " ";
    }
    std::cout << std::endl;

    // Printing list[-5:]
    std::cout << "List from the back: ";
    for (size_t i = list.size() - 5; i < list.size(); ++i) {
        std::cout << list[i] << " ";
    }
    std::cout << std::endl;

    // Setup for random alien selection
    srand(static_cast<unsigned int>(time(0))); // Seed for random generator

    std::map<std::string, std::string> easy_alien = {{"level", "easy"}, {"points", "5"}};
    std::map<std::string, std::string> medium_alien = {{"level", "medium"}, {"points", "10"}};
    std::map<std::string, std::string> hard_alien = {{"level", "hard"}, {"points", "20"}};

    std::vector<std::map<std::string, std::string>> alienFleet = {easy_alien, medium_alien, hard_alien};
    std::vector<std::map<std::string, std::string>> randomAliens;

    // Randomly select aliens
    for (int i = 0; i < 10; ++i) {
        int randomIndex = rand() % alienFleet.size();
        randomAliens.push_back(alienFleet[randomIndex]);
    }

    // Print the randomly selected aliens
    for (const auto& alien : randomAliens) {
        std::cout << "Alien Level: " << alien.at("level") << ", Points: " << alien.at("points") << std::endl;
    }

    // Number collection and summation
    std::vector<int> nummer;
    int flag = 0;
    while (flag < 4) {
        int prompt;
        std::cout << "Add a number: ";
        std::cin >> prompt; // Getting user input
        nummer.push_back(prompt);
        flag++;
    }

    // Summing up the numbers
    int resultat = 0;
    for (const auto& tal : nummer) {
        resultat += tal; // Summing up
    }

    std::cout << "Resultat: " << resultat << std::endl;

    return 0;
}
```

### Key Points of the Conversion:
- The `list` in Python was converted to `std::vector` in C++ for dynamic arrays.
- Slicing was manually implemented using loops since C++ does not support slicing like Python does.
- Dictionaries in Python were converted to `std::map` in C++ to hold key-value pairs.
- Random selection was handled using `rand()` to mimic Python’s `random.choice`.
- Input collection was done using `std::cin`.

Feel free to ask if you have any questions or need further modifications!
